sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float chan;
uniform float inBlack;
uniform float inWhite;
uniform float gamma;
uniform float outBlack;
uniform float outWhite;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 t = saturate((s - inBlack) / max(inWhite - inBlack, 0.001));
    t = pow(t, float3(1.0 / max(gamma, 0.01)));
    float3 lv = mix(float3(outBlack), float3(outWhite), t);
    float3 m = chan < 0.5 ? float3(1.0) : (chan < 1.5 ? float3(1.0, 0.0, 0.0) : (chan < 2.5 ? float3(0.0, 1.0, 0.0) : float3(0.0, 0.0, 1.0)));
    float3 o = mix(s, lv, m);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
